import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String s = next();

        long[] counts = new long[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        Arrays.sort(counts);
        long deleted = 0, previous = s.length() + 1;
        for (int k = 25; k >= 0; k--) {
            long allowed = Math.max(0L, Math.min(counts[k], previous - 1));
            deleted += counts[k] - allowed;
            previous = allowed;
        }
        System.out.println(deleted);
    }
}
